// Parent engineering-ruling fixtures authored NOT_RUN, not owner glyph semantics.
use kni_core::decision_evidence_envelope::PinClaim;
use kni_core::reference_slice::{DrawnGlyph,ReferenceGlyph,ReferenceRing,Point,Span,IntentionalEmptyGlyph,EmptyGlyphIntent,preserve_intentional_empty};
use kni_core::outline_interface::ValidatedClosedGeometry;
use kni_core::method_domains::{prepare_domains,prepare_domains_bound,PolicySlot,DomainMethod,SourceLandmarks,ClosureAliasBinding,DomainBoundary};
fn pin()->PinClaim{PinClaim{algorithm:"fixture".into(),claimed_digest:"unverified".into(),subject_ref:"square".into()}}
fn glyph()->ReferenceGlyph{let o=Point{x:0.,y:0.};ReferenceGlyph{glyph_id:"A".into(),source_pin:pin(),rings:vec![ReferenceRing{start:o,spans:vec![Span::Line{end:Point{x:10.,y:0.}},Span::Line{end:Point{x:0.,y:10.}},Span::Line{end:o}]}],declared_junction_decision_required:false}}
fn slot()->PolicySlot{PolicySlot{domain_method:DomainMethod::LandmarkRegions,domain_method_source:pin(),ranking:None,ranking_binding:None,calibration_revision:None,holdout_evidence:vec![]}}
#[test]fn geometry_adapter_actual_checks(){let g=glyph();let output=DrawnGlyph{glyph_id:g.glyph_id,rings:g.rings};let valid=ValidatedClosedGeometry::validate(output.clone(),pin()).unwrap();assert_eq!(valid.geometry().rings.len(),1);assert_eq!(valid.artifact_claim(pin()).closure_validation_ref().claimed_digest,"unverified");let mut open=output;open.rings[0].spans.pop();assert!(ValidatedClosedGeometry::validate(open,pin()).is_err());}
#[test]fn explicit_empty_not_missing(){let input=IntentionalEmptyGlyph{glyph_id:"space".into(),source_pin:pin(),intent:EmptyGlyphIntent::Space};assert!(preserve_intentional_empty(input.clone()).rings.is_empty());let svg=kni_core::svg_outline::intentional_empty_svg(&input,kni_core::svg_outline::SourceViewport{x:0.,y:0.,width:10.,height:10.}).unwrap();assert_eq!(svg,"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 10 10\"></svg>");}
#[test]fn empty_domains_and_ambiguous_claims(){let mut g=glyph();g.rings[0].spans.clear();let result=prepare_domains(&g,&[],&slot());assert!(result.domains.is_empty());assert!(matches!(result.unresolved.last(),Some(DomainBoundary::EmptySourceRing{ring_index:0})));let g=glyph();let a=SourceLandmarks{ring_index:0,endpoint_indices:vec![0,1],source_evidence:pin()};let mut b=a.clone();b.source_evidence.claimed_digest="different".into();let result=prepare_domains(&g,&[a,b],&slot());assert!(result.domains.is_empty());assert!(result.unresolved.iter().any(|v|matches!(v,DomainBoundary::AmbiguousLandmarkSources{..})));}
#[test]fn raw_order_and_explicit_alias(){let g=glyph();let a=SourceLandmarks{ring_index:0,endpoint_indices:vec![3,1],source_evidence:pin()};assert!(prepare_domains(&g,&[a.clone()],&slot()).domains.is_empty());let b=ClosureAliasBinding{ring_index:0,source_evidence:pin(),alias_endpoint:3,canonical_endpoint:0};let result=prepare_domains_bound(&g,&[a],&slot(),&[b]);assert_eq!(result.domains.len(),2);assert_eq!(result.landmark_orders[0].raw_source_indices,vec![3,1]);assert_eq!(result.landmark_orders[0].derived_cyclic_indices,vec![0,1]);}
#[test]fn frame_no_silent_flip(){use kni_core::output_binding::{FrameFillBinding,AxisDirection,BindingObservation,inspect};let b=FrameFillBinding{source_frame:pin(),target_frame:pin(),correspondence:pin(),source_units_per_em:1000,target_units_per_em:1000,source_y:AxisDirection::Down,target_y:AxisDirection::Up,source_fill:kni_core::cff_fill::SourceFill::NonZero};assert_eq!(inspect(&b),vec![BindingObservation::ExplicitTransformRequired,BindingObservation::FillEquivalenceUnresolved]);}
